// Los hilos de WhatsApp cuyo silencio (`silencio_hasta`, lo pone `WHATSAPP · Eco del
// móvil` cuando alguien contesta desde la app) ya ha pasado. Cada uno sale como un item
// con la hora de AHORA: el PATCH de después solo libera el silencio si sigue vencido a
// esa hora, así que un eco que lo haya alargado entretanto gana.
const cfg = $('Config (editar por tenant)').first().json;
const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/conversation_sessions ' + code + ': ' + JSON.stringify(body.errors || body));
}
const filas = Array.isArray(body.data) ? body.data : [];
const ahora = new Date().toISOString();
return filas.map((s) => ({ json: {
  id: s.id, session_key: s.session_key, modo: s.modo || 'auto',
  silencio_hasta: s.silencio_hasta, ventana_hasta: s.ventana_hasta || null,
  ahora, directus_base_url: cfg.directus_base_url, tenant: cfg.tenant,
  max_retraso_minutos: Number(cfg.max_retraso_minutos) || 30,
} }));

// Solo sigue lo que de verdad se ha liberado y merece que Lucía conteste. Todo lo demás
// se queda con el silencio vaciado y nada más.
const sesiones = $('Code · Una por sesión').all();
const salida = [];
$input.all().forEach((it, i) => {
  const s = sesiones[i] && sesiones[i].json;
  if (!s) return;
  const r = it.json ?? {};
  const code = r.statusCode ?? 0;
  const body = (r.body ?? r) || {};
  if (code >= 300 || (body && body.errors)) {
    throw new Error('Directus PATCH conversation_sessions ' + code + ': ' + JSON.stringify(body.errors || body));
  }
  // Vacío = un eco lo alargó entre la consulta y el PATCH: alguien sigue contestando.
  if (!Array.isArray(body.data) || body.data.length === 0) return;
  // Lo ha cogido una persona desde el panel: el hilo es suyo, no de Lucía.
  if (s.modo === 'humano') return;
  // Un silencio vencido hace mucho (n8n parado, o el primer despliegue) no se retoma:
  // contestar ahora a algo de hace horas sería más raro que no contestar.
  const fin = Date.parse(s.silencio_hasta);
  if (!Number.isFinite(fin) || Date.now() - fin > s.max_retraso_minutos * 60000) return;
  // Con la ventana de 24 h cerrada no se le puede escribir texto libre.
  const ventana = s.ventana_hasta ? Date.parse(s.ventana_hasta) : NaN;
  if (!Number.isFinite(ventana) || ventana <= Date.now()) return;
  salida.push({ json: s });
});
return salida;

// ¿Quedó el cliente sin respuesta? Se mira el final del hilo: los mensajes del cliente
// que van detrás de la última salida (de quien sea). Si no hay ninguno, la persona le
// contestó o no hacía falta, y Lucía no tiene nada que decir.
const sesiones = $('Code · ¿Liberada?').all();
const salida = [];
$input.all().forEach((it, i) => {
  const s = sesiones[i] && sesiones[i].json;
  if (!s) return;
  const r = it.json ?? {};
  const code = r.statusCode ?? 0;
  const body = (r.body ?? r) || {};
  if (code >= 300 || (body && body.errors)) {
    throw new Error('Directus /items/conversation_messages ' + code + ': ' + JSON.stringify(body.errors || body));
  }
  const filas = Array.isArray(body.data) ? body.data : []; // del más nuevo al más viejo
  const pendientes = [];
  for (const m of filas) {
    if (m.direccion === 'entrante' && m.autor === 'cliente') pendientes.push(m);
    else break;
  }
  if (!pendientes.length) return;
  // Un mensaje que llegó DESPUÉS de acabar el silencio es de Entry: lo está contestando
  // (o ya lo contestó y aún no se ve). Retomarlo aquí sería contestar dos veces.
  const fin = Date.parse(s.silencio_hasta);
  const ultimo = Date.parse(pendientes[0].created_at);
  if (Number.isFinite(fin) && Number.isFinite(ultimo) && ultimo > fin) return;
  const texto = pendientes.reverse()
    .map((m) => (m.texto || '').toString().trim()).filter(Boolean).join('\n');
  if (!texto) return;
  const tel = s.session_key.replace(/^whatsapp:/, '');
  salida.push({ json: {
    session_key: s.session_key, message: texto, tenant: s.tenant,
    from: { phone: '+' + tel, name: null },
  } });
});
return salida;
